	@Test
	void canonicalInterningUsesEveryStructuralIdentityDimension() {
		long[] factors = { 0b101L, 0b10L };
		long[] masks = { 0b11L };
		FrontierStateKey key = key(factors, FrontierLayout.of("x", "y"), masks, 7L, 11L, 13L, 17L, 19L, 1, 2);
		factors[0] = 0L;
		masks[0] = 0L;
		FrontierStateKey equivalent = key(
				new long[] { 0b101L, 0b10L },
				FrontierLayout.of("x", "y"),
				new long[] { 0b11L },
				7L,
				11L,
				13L,
				17L,
				19L,
				1,
				2);

		assertEquals(equivalent, key);
		assertEquals(equivalent.hashCode(), key.hashCode());
		assertNotEquals(key, key(new long[] { 0b111L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 11L, 13L, 17L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, FrontierLayout.of("y", "x"),
				new long[] { 0b11L }, 7L, 11L, 13L, 17L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b01L },
				7L, 11L, 13L, 17L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				8L, 11L, 13L, 17L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 12L, 13L, 17L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 11L, 14L, 17L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 11L, 13L, 18L, 19L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 11L, 13L, 17L, 20L, 1, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 11L, 13L, 17L, 19L, 2, 2));
		assertNotEquals(key, key(new long[] { 0b101L, 0b10L }, key.frontier(), new long[] { 0b11L },
				7L, 11L, 13L, 17L, 19L, 1, 3));
	}

