	@Test
	void exactZeroRequiresDatabaseProofAndAnExactZeroBound() {
		EvidenceStateSummary exactZero = EvidenceStateSummary.exact(0.0d);

		assertEquals(EvidenceGuarantee.DATABASE_EXACT, exactZero.guarantee());
		assertEquals(EvidenceZeroStatus.EXACT_ZERO, exactZero.zeroStatus());
		assertEquals(0.0d, exactZero.certifiedUpperBound());
		assertThrows(IllegalArgumentException.class,
				() -> summary(EvidenceGuarantee.MEASURE_UNBIASED, EvidenceZeroStatus.EXACT_ZERO, 0.0d, 0.0d));
		assertThrows(IllegalArgumentException.class,
				() -> summary(EvidenceGuarantee.DATABASE_EXACT, EvidenceZeroStatus.EXACT_ZERO, 0.0d, 1.0d));
	}

