	@Test
	void closedArenaRejectsStateAccess() {
		FrontierStateArena arena = new FrontierStateArena(64 * 1024L);
		EvidenceStateRef reference = arena.append(FrontierLayout.empty(), EvidenceStateSummary.exact(1.0d));
		arena.close();

		assertThrows(IllegalStateException.class, () -> arena.summary(reference));
		assertThrows(IllegalStateException.class, arena::size);
		assertEquals(0L, arena.allocatedBytes());
	}

	private static EvidenceStateSummary summary(EvidenceGuarantee guarantee, EvidenceZeroStatus zeroStatus,
			double pointRows, double upperRows) {
		return new EvidenceStateSummary(
				pointRows,
				0.0d,
				upperRows,
				0.95d,
				EvidenceIntervalKind.POINTWISE,
				1.0d,
				2.0d,
				3.0d,
				4.0d,
				pointRows == 0.0d ? 0.0d : 0.5d,
				upperRows,
				guarantee,
				zeroStatus,
				"");
	}

	private static long arrayBytes(int length, int elementBytes) {
		long bytes = 16L + (long) length * elementBytes;
		return bytes + 7L & ~7L;
	}

	private static FrontierStateKey key(
			long[] factors,
			FrontierLayout frontier,
			long[] masks,
			long semanticScope,
			long correlationScope,
			long continuationObjective,
			long snapshotStoreId,
			long snapshotEpoch,
			int laneRole,
			int seedVersion) {
		return FrontierStateKey.of(
				factors,
				frontier,
				masks,
				semanticScope,
				correlationScope,
				continuationObjective,
				snapshotStoreId,
				snapshotEpoch,
				laneRole,
				seedVersion);
	}
